import bisect

def solve(gas_stations, destination):
    left, right = 0, destination
    while left < right:
        mid = (left + right) // 2
        fuel = 0
        tank = float('inf')
        for i in range(len(gas_stations)):
            fuel += gas_stations[i]
            if fuel < mid:
                if tank < mid:
                    tank = mid
                fuel = 0
            fuel -= (i + 1)
        if tank >= destination:
            right = mid
        else:
            left = mid + 1
    return left

