import functools

def sort_with_twos(arr):
    @functools.lru_cache(maxsize=None)
    def dfs(i, m):
        if i == len(arr):
            return True
        for j in range(m, -1, -1):
            if (1 << j) <= i:
                arr[i] -= 1
                if dfs(i + (1 << j), j):
                    return True
                arr[i] += 1
        return False

    for i in range(len(arr)):
        if not dfs(i, len(bin(len(arr))[2:].count('1'))):
            return False
    return True

def solve():
