                if tree[i] > tree[i + 1]:
                    diff = tree[i] - tree[i + 1]
                    tree[i] -= diff
                    for j in range(i + math.log2(i) + 1):
                        tree[2 ** j + i] -= diff
                    tree[i + 1] += diff
                i += 1
        print("YES" if all(i <= j for i, j in zip(a, a[1:])) else "NO")

import math

def bit_update(bit, n, pos, val):
    while pos <= n:
        bit[pos] += val
        pos += pos & -pos

def bit_sum(bit, n, pos):
    sum = 0
    while pos > 0:
        sum += bit[pos]
        pos -= pos & -pos
    return sum

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        bit = [0] * (2 * n)
        for i in range(1, len(a) + 1):
            bit_update(bit, len(a), i, -1)
        for i in range(1, len(a) + 1):
            a[i - 1] += bit_sum(bit, len(a), i)
        sorted_a = sorted(a)
        if a == sorted_a:
            print("YES")
        else:
            print("NO")

