def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        tree = [0] * (2 * n)

        def update(i, x):
            i += n
            while i > 0:
                tree[i] += x
                i -= i & -i

        def sum_range(l, r):
            s = 0
            r += 1
            while l < r:
                if l & 1:
                    s += tree[l]
                    l += 1
                l = l // 2
                if r % 2:
                    s += tree[r]
                    r -= 1
                r = r // 2
            return s

