from collections import deque

def bfs(graph, start, end):
    queue = deque([(start, 1)])
    visited = set()
    while queue:
        node, steps = queue.popleft()
        if node == end:
            return steps
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                queue.append((neighbor, steps + 1))
    return -1

