import itertools

def solve(n):
    if n <= 3:
        return list(range(1, n + 1))

    # Find the largest number that can be a multiple of 3 times the last number
    max_last = math.ceil(3 * (2 * n - 1) / 2)

    # Generate all possible combinations of numbers up to max_last
    combinations = list(itertools.combinations_with_replacement(range(1, max_last + 1), n - 2))

    # Iterate through all combinations and check if the condition is satisfied
    for combination in combinations:
        current = [1]
        for i in range(2, n):
            next_num = current[-1] + sum(combination[:i])
            if 3 * next_num % (sum(combination[:i]) + current[-1]) != 0:
                current.append(next_num)
                break
        else:
            # If no such number is found, return an invalid solution
            return [-1] * n

    # Add the remaining numbers
    for i in range(len(combination)):
        current.append(sum(combination[:i + 1]))

    # Return the solution
    return current

