        if x < 0 or x >= n or y < 0 or y >= m:
            return
        if grid[x][y] == '.':
            return
        if rings[ring - 1]:
            rings[ring - 1] -= 1
            points += ring
        dfs(x + dx[dir], y + dy[dir], ring)
        dfs(x - dx[dir], y - dy[dir], ring)
        dfs(x + dx[dir] * 2, y + dy[dir] * 2, ring - 1)
        dfs(x - dx[dir] * 2, y - dy[dir] * 2, ring - 1)

    n, m = map(int, input().split())
    grid = [list(input().strip()) for _ in range(n)]
    points = 0
    rings = list(reversed([int(input()) for _ in range(5)]))
    dx, dy = [1, 0], [0, 1]
    dir = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                dfs(i, j, 5)
                dir = (dir + 1) % 4
    print(points)

