import sys

def solve(b):
    def is_valid(a):
        if len(a) < len(b) or len(a) > 2 * len(b):
            return False
        a_i = [a[i] for i in range(1, len(a)) if a[i - 1] <= a[i]]
        return a[0] == b[0] and a_i == b[1:]

    def find_sequence(i, a):
        if i == len(b):
            return True
        for j in range(i, len(a)):
            if b[i] == a[j] and find_sequence(i + 1, a[:j] + a[j + 1:]):
                return True
        return False

    def backtrack(i, a):
        if i == len(b):
            return True
        for j in range(i, len(a)):
            if b[i] <= a[j] and not any(a[k] > a[j] for k in range(i, j)):
                a[i] = b[i]
                if backtrack(i + 1, a):
                    return True
                a[i] = 0
        return False

    max_len = 2 * len(b)
    for m in range(len(b), max_len + 1):
        a = [0] * m
        if find_sequence(0, a):
            a[0] = b[0]
            backtrack(1, a)
            if is_valid(a):
                print(m)
                print(*a)
                return
    print(-1)

import heapq

def solve():
    while True:
        n = int(input())
        if not n:
            break
        sequence = list(map(int, input().split()))
        heap = []
        for num in sequence:
            heapq.heappush(heap, num)
        new_sequence = []
        while heap and heap[0] <= heap[1]:
            new_sequence.append(heapq.heappop(heap))
        if not new_sequence:
            print(f"0")
        else:
            max_len = 2 * len(new_sequence)
            for _ in range(len(new_sequence), max_len):
                new_sequence.append(new_sequence[-1])
            print(f"{len(new_sequence)}\n{' '.join(map(str, new_sequence))}")

