    parents = list(range(n))
    size = [1] * n

    for num in a:
        if num % 2 == 1:
            odd_sum += num
        else:
            even_sum += num

    if odd_sum == 0:
        print("YES")
        return

    union_map = defaultdict(list)
    for i in range(n):
        root = find(i)
        union_map[root].append(a[i])

    for root, nums in union_map.items():
        if len(nums) > 1:
            for i in range(len(nums) - 1):
                for j in range(i + 1, len(nums)):
                    if nums[i] + nums[j] & 1 == 0:
                        union(root, find(nums[i] ^ nums[j]))

    for root in union_map:
        if len(union_map[root]) == 1:
            print("NO")
            return

    print("YES")

