import sys
from heapq import heappush, heappop

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Initialize two heaps: one for increasing elements and one for decreasing elements
        inc_heap, dec_heap = [], []
        for num in a:
            if not inc_heap or num > inc_heap[0]:
                heappush(inc_heap, num)
            if not dec_heap or num < dec_heap[0]:
                heappush(dec_heap, -num)

        # If both heaps are sorted, the array is already not sorted
        if inc_heap and dec_heap:
            print(0)
            continue

        # Perform operations to make the array not sorted
        operations = 0
        while inc_heap and dec_heap:
            if inc_heap[0] > dec_heap[0]:
                heappop(inc_heap)
                operations += 1
            else:
                heappop(dec_heap)
                operations += 1

        print(operations)

