import sys

def solve(n, k, a):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + abs(a[i - 1] - a[i])

    def dfs(start, cur_group, cur_sum):
        if cur_group == k:
            return cur_sum
        min_sum = float('inf')
        for i in range(start, n):
            min_sum = min(min_sum, dfs(i + 1, cur_group + 1, cur_sum + dp[i + 1] - dp[start]))
        return min_sum

    return dfs(1, 1, 0)

