import sys

def solve(n, k, x):
    if n < x or n > k or x == 1:
        return "NO"

    if n == x:
        return "YES\n1\n[]"

    diff = n - x
    for i in range(1, k + 1):
        if i != x and diff % i == 0:
            quotient, remainder = divmod(diff, i)
            if quotient > 0 and not any(j == x for j in range(1, k + 1)):
                m = quotient + (remainder > 0)
                result = list(combinations(range(1, k + 1), m))
                for r in result:
                    if sum(r) == n:
                        return "YES\n{}".format(m) + "\n" + " ".join(map(str, r))

    return "NO"

