from collections import deque

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        if n == 1:
            print(1)
            continue
        q = deque([(1, 0)])
        powers_of_two = [2 ** i for i in range(n.bit_length() + 1)]
        visited = set()
        total = 0
        while q:
            node, level = q.popleft()
            if level == n - 1:
                total += node
            for child in (node * 2, node * 2 + 1):
                if child < powers_of_two[-1] and child not in visited:
                    q.append((child, level + 1))
                    visited.add(child)
        print(total)

