from typing import List

def bit_sum(bit: List[int], n: int, l: int, r: int) -> int:
    s = 0
    while l <= r:
        s += bit[l]
        l += (l & -l)
        if r != l:
            s += bit[r + 1]
            r -= (r & -r)
    return s

def bit_update(bit: List[int], n: int, l: int, r: int, i: int, delta: int) -> None:
    if i > n:
        return
    while i <= n:
        bit[i] += delta
        i += (i & -i)

def solve() -> None:
    n_test_cases = int(input())
    for _ in range(n_test_cases):
        n = int(input())
        bit = [0] * (n * 2)
        bit_update(bit, n * 2, 1, 1, n, 1)
        print(bit_sum(bit, n * 2, 1, n))

