def solve():
    def power_set(nums: List[int]):
        n = len(nums)
        power_set_list = [[] for _ in range(1 << n)]
        for i in range(1, 1 << n):
            for j in range(n):
                if i & (1 << j):
                    power_set_list[i] += [nums[j]]
        return power_set_list

    def bit_count(n: int):
        return bin(n).count('1')

    def find_initial_pair(nums: List[int]):
        power_set = power_set(nums)
        for i in range(1, len(nums)):
            for j in range(i + 1, len(nums)):
                if bit_count(nums[i] - nums[j]) == 1:
                    return nums[i], nums[j]

