def solve(n, books):
    skills = [0] * 2
    for book in books:
        minutes, skill = book
        skills = list(map(lambda x, y: x | y, skills, [1 << (skill - 1) & skill for _ in range(minutes)]))

    def dfs(remaining_skills, remaining_minutes, current_minutes=0):
        if not remaining_skills:
            return current_minutes
        if not remaining_minutes:
            return -1

        min_time = float('inf')
        for book in books:
            minutes, skill = book
            if remaining_minutes >= minutes and (remaining_skills & (1 << (skill - 1))) != 0:
                new_minutes = dfs(remaining_skills ^ (1 << (skill - 1)), remaining_minutes - minutes)
                min_time = min(min_time, new_minutes + current_minutes)

        return min_time

    return dfs(skills, sum(minutes for _, minutes in books))

