import re

def find_longest_non_palindrome(s):
    def is_palindrome(sub):
        return sub == sub[::-1]

    def find_longest_non_palindrome_helper(s, start, length):
        if length == 0:
            return 0
        if length == 1:
            return 1 if not is_palindrome(s[start]) else 0

        max_length = 0
        for i in range(start + 1, len(s) - length + 1):
            sub = s[start:i] + s[i + 1:start + length]
            if not is_palindrome(sub):
                max_length = max(max_length, length + find_longest_non_palindrome_helper(s, i + 1, length - 1))

        return max_length

    return find_longest_non_palindrome_helper(s, 0, len(s)) if len(s) > 0 else -1

