import sys

def solve(n, k):
    if k > (n - 1) * n // 2 or k < 0:
        return "NO"

    if n == 1:
        return "YES\n1"

    pairs = set()
    for i in range(1, n):
        for j in range(i + 1, n):
            pairs.add((i, j))
            if (i + j) % 2 == 1:
                pairs.remove((j, i))

    if k == len(pairs):
        res = []
        for i, j in combinations(range(1, n + 1), n):
            if len(set(i - j for i, j in zip(res, i)) & set([1, -1])) == k:
                break
        for i in res:
            print(i, end=' ')
        print()
        return

    for i in range(1, n):
        if i * i > 2 * k:
            break
        for j in range(i + 1, n):
            if (i * j == k or (i + j) * (n - i - j) == k):
                pairs.remove((i, j))
                pairs.remove((j, i))
                res = list(combinations(range(1, n + 1), n))
                for r in res:
                    if len(set(r[i] * r[j] for i, j in zip(r, r[1:])) & set([1, -1])) == k:
                        for e in r:
                            print(e, end=' ')
                        print()
                        return
    return "NO"

