        ans = [1]
        for i in range(1, n):
            if dp[i][0] - dp[i - 1][0] >= k - dp[n - 1][1] + dp[i - 1][1]:
                ans.append(-1)
                k -= dp[i][0] - dp[i - 1][0]
        ans.append(1)
