from collections import deque

def solve(s):
    queue = deque()
    smiley_count = 0
    for i in range(len(s)):
        if s[i] == '^':
            if not queue or queue[-1] != '_':
                queue.append(i)
            smiley_count += 1
        elif s[i] == '_':
            if queue and queue[0] == i:
                queue.popleft()
                smiley_count -= 1
            queue.append(i)

    missing_smileys = len(s) - smiley_count
    if not missing_smileys:
        return 0

    if not queue:
        return missing_smileys

    for i in range(len(s), len(s) + missing_smileys):
        if i - len(s) % 2 == 1:
            queue.append(i)
        else:
            queue.append('_')

    result = ''
    for i in range(len(s)):
        if i in queue:
            result += '^'
        else:
            result += '_'

    return len(result) - len(s)

