def solve(n, k, opinions):
    # Create a dictionary to store the number of agreements and disagreements for each opinion
    counts = defaultdict(lambda: [0, 0])
    for member in opinions:
        for i in range(k):
            if member[i] == '+':
                counts[i][0] += 1
            else:
                counts[i][1] += 1

    # Find the opinions with the minimum number of agreements and maximum number of disagreements
    min_agree, max_disagree = float('inf'), -float('inf')
    for opinion, (agree, disagree) in counts.items():
        min_agree = min(min_agree, agree)
        max_disagree = max(max_disagree, disagree)

    # Calculate the maximum number of members that can remain in the club
    max_members = n - min_agree + max_disagree - k + 1
    return max_members

