import math

def solve(n):
    if n == 1:
        return 0, []

    steps, spells = math.ceil(math.log2(n)) if n & 1 else math.ceil(math.log2(n)) + 1, []

    for _ in range(steps):
        if n & 1:
            spells.append(2)
            n = 2 * n + 1
        else:
            spells.append(1)
            n = 2 * n - 1

    return steps, spells

