from math import log2, sin, cos
from cmath import exp

def nfft(a):
    n = len(a)
    if n == 1:
        return a
    even = nfft(a[::2])
    odd = nfft(a[1::2])
    evens = [even[i] + exp(2j * 2 * pi * k / n) * even[i + n // 2] for i in range(n // 2)]
    odds = [odd[i] + exp(2j * 2 * pi * k / n) * odd[i + n // 2] for i in range(n // 2)]
    return [evens[i] + odds[i] for i in range(n)]

def inv_fft(a):
    n = len(a)
    a_inv = [1] * n
    for k in range(1, n):
        for i in range(k):
            p = (k // 2 ** i) << i
            a_inv[i] += a_inv[i + p]
            a_inv[i + p] -= a_inv[i]
    for k in range(n - 1, 0, -1):
        for i in range(k):
            p = (k // 2 ** (k - i)) << (k - i)
            a_inv[i] += a_inv[i + p]
            a_inv[i + p] -= a_inv[i]
    for i in range(n):
        a_inv[i] /= n
    return [round(x.real) for x in a_inv]

def solve():
