def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Calculate the number of 1's in the binary representation of each number
        ones = [bin(x).count('1') for x in a]

        # If the number of 1's is even for all numbers, then XOR with 0 will give 0
        if all(x % 2 == 0 for x in ones):
            x = 0
        else:
            # Find the number that has an odd number of 1's and XOR it with 1 to make it even
            odd_ones = [x for x in ones if x % 2 != 0]
            if odd_ones:
                x = reduce(lambda a, b: a ^ b, odd_ones) ^ 1
            else:
                x = -1

        stdout.write(str(x) + '\n')

