from collections import deque

def solve(n, m, actions):
    recent = deque([i for i in range(1, n + 1))]
    removal_times = [-1] * n
    actions.sort()

    for action in actions:
        if recent[0] == action:
            recent.rotate(-1)
        else:
            recent.append(recent.popleft())
            removal_times[recent[0] - 1] = actions.index(action) + 1

    return removal_times

from collections import deque

def solve(n, m, actions):
    recent = deque([i for i in range(1, n + 1))]
    removal_times = [-1] * n
    for action, time in zip(actions, range(1, m + 1)):
        if recent[0] == action:
            recent.rotate(-1)
        else:
            recent.popleft()
            removal_times[action - n - 1] = time
    return removal_times

