from collections import defaultdict

def find(x, parents):
    if parents[x] != x:
        parents[x] = find(parents[x], parents)
    return parents[x]

def union(x, y, parents):
    root_x = find(x, parents)
    root_y = find(y, parents)
    parents[root_x] = root_y

def solve(n, m, x1, y1, x2, y2):
    parents = list(range(n * m + 1))
    obstacles = 0

    # Create adjacency list
    adjacency_list = defaultdict(list)
    for i in range(n):
        for j in range(m):
            if i > 0:
                adjacency_list[(i, j)].append((i - 1, j))
            if i < n - 1:
                adjacency_list[(i, j)].append((i + 1, j))
            if j > 0:
                adjacency_list[(i, j)].append((i, j - 1))
            if j < m - 1:
                adjacency_list[(i, j)].append((i, j + 1))

    # Mark start and end points as visited
    visited = set()
    visited.add((x1, y1))
    stack = [(x1, y1)]

    while stack:
        x, y = stack.pop()
        for neighbor in adjacency_list[(x, y)]:
            if find(neighbor) != find((x, y)):
                union(neighbor, (x, y), parents)
                obstacles += 1
            if (neighbor not in visited):
                visited.add(neighbor)
                stack.append(neighbor)

    # Mark start and end points' connected components as visited
    visited.add((x2, y2))
    stack = [(x2, y2)]
    while stack:
        x, y = stack.pop()
        for neighbor in adjacency_list[(x, y)]:
            if find(neighbor) != find((x2, y2)):
                union(neighbor, (x, y), parents)
                obstacles += 1

    return obstacles

