import collections

def create_trie(prefixes_suffixes):
    trie = collections.defaultdict(collections.defaultdict, {'#': None})
    for prefix_suffix in prefixes_suffixes:
        current = trie
        for char in reversed(prefix_suffix):
            if char not in current:
                current[char] = collections.defaultdict(collections.defaultdict, {'#': None})
            current = current[char]
    return trie

def is_palindrome(trie, prefix_suffix):
    current = trie
    for char in prefix_suffix:
        if char not in current:
            return False
        current = current[char]
    return current['#'] is not None

