import itertools

def solve(health):
    n = len(health)
    if n == 1:
        return health[0]

    min_spells = float('inf')
    for i, h in enumerate(health):
        if h == 0:
            continue
        pairs = list(itertools.combinations(range(n), 2))
        for pair in pairs:
            if pair[0][0] == i or pair[1][0] == i:
                continue
            if health[pair[0][0]] > 1 and health[pair[1][0]] > 1:
                new_health = health.copy()
                new_health[pair[0][0]] -= 1
                new_health[pair[1][0]] -= 1
                if not any(new_health):
                    return 1 + solve(new_health)

        # If we can't kill the current monster with one spell, try to kill it with two spells
        if health[i] > 1:
            new_health = health.copy()
            new_health[i] -= 2
            if not any(new_health):
                min_spells = min(min_spells, 1 + solve(new_health))

    # If we can't kill all monsters with one or two spells, we need to kill them one by one
    if min_spells == float('inf'):
        min_spells = n
        for h in health:
            min_spells += h - 1

    return min_spells

