def solve(n, s, r):
    if n == 2:
        return [6, 1] if r == 1 else [6, 6]

    dp = {}
    for i in range(2, n + 1):
        for j in range(i + 1, min(i + 6, n + 1)):
            if (i, j) in dp:
                continue
            for k in range(1, 7):
                if k > j:
                    break
                if s - k - (j - i) not in dp:
                    dp[(i, j)] = [k] + dp[(i + 1, j - 1)]
                else:
                    dp[(i, j)] = dp[(i, j)] + dp[(i + 1, j - 1)]

    solutions = []
    for i in range(2, n + 1):
        for j in range(i + 1, min(i + 6, n + 1)):
            if (i, j) in dp:
                solutions.append(dp[(i, j)] + [r])

    return list(itertools.chain.from_iterable(solutions))

