                for j in range(i, n):
                    temp = s[:i] + s[j:]
                    temp_q = deque(temp)
                    if len(temp_q) % 2 == 1:
                        continue
                    for k in range(len(temp_q) // 2):
                        if temp_q.popleft() != temp_q[-1 - k]:
                            break
                    else:
                        s[:] = temp
                        break
            if s == list(reversed(s)):
                print("Yes")
            else:
