import functools

def solve():
    from collections import defaultdict

    def bit_count(n):
        return functools.reduce(lambda a, x: a + (x // 2 ^ x % 2), range(1, n + 1), 0)

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        odd_count = bit_count(n)
        if odd_count < 3:
            print("NO")
            continue
        odd_indices = defaultdict(list)
        for i, num in enumerate(a):
            if num & 1:
                odd_indices[bit_count(num)].append(i)
        for i in range(1, len(odd_indices)):
            if odd_indices[i] and odd_indices[odd_count - i]:
                j, k = odd_indices[i]
                l = [x for x in odd_indices[odd_count - i] if x != j and x != k]
                if l:
                    print("YES")
                    print(f"{j + 1} {k + 1} {l[0] + 1}")
                else:
                    print("YES")
                    print(f"{j + 1} {k + 1} {n + 1 - j - k}")

