        if all(s[i] == 'L' or s[i] == 'R' for i in range(n)):
            print(0)
            continue

        # Use BFS to find a pair of lamps that can be swapped to illuminate all trophies
        q = deque([(0, 0)])
        visited = set()
        while q:
            i, direction_sum = q.popleft()
            if i == n - 1:
                print(i)
                break
            if (i, -direction_sum) not in visited:
                q.append((i + 1, -direction_sum))
                visited.add((i, -direction_sum))
            if (i + 1, direction_sum + 2) not in visited:
                q.append((i + 2, direction_sum + 2))
                visited.add((i + 2, direction_sum + 2))
        else:
            print(-1)

