from collections import deque

def solve(n, s):
    q = deque([(0, 0)])
    visited = set()
    visited.add(0)

    while q:
        i, count = q.popleft()
        if count == n:
            return i
        for j in range(i - 1, -1, -1):
            if s[j] == 'L' and j not in visited:
                visited.add(j)
                q.append((j, count + 1))
        for j in range(i + 1, n):
            if s[j] == 'R' and j not in visited:
                visited.add(j)
                q.append((j, count + 1))

    return -1

