    if len(letters) != 2 or letters[0] != 'a' or letters[1] != 'b':
        return ":("

    n = len(s) // 3
    for a, b, c in itertools.product(letters, repeat=3):
        if all(a <= b <= c for b in zip(a, c)) or all(c <= b <= a for b in zip(a, c)):
            return " ".join(a * n + b * (n + 1) + c * (n + 2))

    return ":("

