        n = len(a)
        dp = [[0] * 2 for _ in range(n)]
        for i in range(1, n):
            for j in range(i):
                dp[i][0] = min(dp[i][0], dp[j][1] + abs(int(''.join(a[j:i]), 2)) + (i - j - 1) * 2)
                dp[i][1] = min(dp[i][1], dp[j][0] + (i - j))
        return dp[n - 1][0]

