import itertools

def slope(x1, y1, x2, y2):
    if x1 == x2:
        return None
    return (y2 - y1) / (x2 - x1)

def is_horizontal(slope):
    return slope is None or slope == 0

def is_vertical(slope):
    return slope is None or slope == float('inf')

def cut_triangle(x1, y1, x2, y2, x3, y3):
    points = [(x1, y1), (x2, y2), (x3, y3)]
    areas = abs(0.5 * math.fabs(sum(map(lambda p1, p2: (p1[0] * p2[1] - p1[1] * p2[0]), zip(points[1:], points[:-1]))))
    if areas == 0:
        return False

    slopes = [slope(x1, y1, x2, y2), slope(x2, y2, x3, y3), slope(x3, y3, x1, y1)]
    if any(is_horizontal(slope) and any(is_vertical(slope2) for slope2 in slopes) for slope in slopes):
        return True
    return False

