def centroid(x1, y1, x2, y2, x3, y3):
    x = (x1 + x2 + x3) / 3
    y = (y1 + y2 + y3) / 3
    return x, y

def distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def solve():
    cases = int(input())
    for _ in range(cases):
        x1, y1 = map(int, input().split())
        x2, y2 = map(int, input().split())
        x3, y3 = map(int, input().split())

        # Calculate the centroid
        x, y = centroid(x1, y1, x2, y2, x3, y3)

        # Check if the centroid is on the x-axis or y-axis
        if abs(y - (y1 + y2 + y3) / 3) < 1e-9:
            print("YES")
        elif abs(x - (x1 + x2 + x3) / 3) < 1e-9:
            print("YES")
        else:
            print("NO")

