def solve():
    import itertools

    def is_valid(word):
        # Generate all possible sequences of pressing a key twice and once
        sequences = list(itertools.chain.from_iterable(itertools.product([True, False], repeat=len(word))))

        # Check if any sequence results in the given word
        for sequence in sequences:
            current_letter = ''
            for i, is_double in enumerate(sequence):
                if is_double:
                    current_letter += word[i] * 2
                else:
                    current_letter += word[i]
            if current_letter == word:
                return True
        return False

    t = int(input())
    for _ in range(t):
        n = int(input())
        word = input()
        if is_valid(word):
            print("YES")
        else:
            print("NO")

