from typing import List

class SegmentTree:
    def __init__(self, n: int):
        self.n = n
        self.size = 4 * n
        self.tree = [0] * self.size
        self.lazy = [0] * self.size

    def build(self, arr: List[int], k: int, l: int, r: int):
        if l == r:
            self.tree[k] = arr[l]
            return arr[l]

        m = (l + r) // 2
        self.build(arr, 2 * k, l, m)
        self.build(arr, 2 * k + 1, m + 1, r)
        self.tree[k] = min(self.tree[2 * k], self.tree[2 * k + 1])
        return self.tree[k]

    def update(self, k: int, l: int, r: int, i: int, x: int, v: int):
        if i < l or r < i:
            return
        if l == r:
            self.tree[k] = v
            self.lazy[k] = v
            return

        m = (l + r) // 2
        if i <= m:
            self.update(2 * k, l, m, i, x, v)
        else:
            self.update(2 * k + 1, m + 1, r, i, x, v)
        self.tree[k] = min(self.tree[2 * k], self.tree[2 * k + 1])

    def query(self, k: int, l: int, r: int, i: int, j: int) -> int:
        if self.lazy[k]:
            self.update(2 * k, 1, self.n, i, j, self.lazy[k])
            self.lazy[k] = 0
        if i > r or j < l:
            return sys.maxsize
        if i <= l and r <= j:
            return self.tree[k]
        m = (l + r) // 2
        return min(self.query(2 * k, l, m, i, j), self.query(2 * k + 1, m + 1, r, i, j))

    def range_sum(self, l: int, r: int) -> int:
        return self.query(1, 1, self.n, l, r)

def solve():
    n = int(input())
