def solve():
    def xor_bits(a, b, pos):
        return (a << pos) ^ (b << pos) | (a >> (32 - pos)) ^ (b >> (32 - pos))

    def process(arr):
        n = len(arr)
        max_val = float('-inf')
        min_val = float('inf')

        for i in range(n):
            for j in range(i + 1, n):
                for pos in range(32):
                    new_arr = arr.copy()
                    new_arr[i] = xor_bits(new_arr[i], new_arr[j], pos)
                    new_arr[j] = xor_bits(new_arr[i], new_arr[j], pos)
                    if max(new_arr) - min(new_arr) > max_val - min_val:
                        max_val = max(new_arr)
                        min_val = min(new_arr)

        return max_val - min_val

    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        arr = list(map(int, input().strip().split()))
        print(process(arr))

def solve():
    import sys
    from itertools import accumulate
    input = sys.stdin.readline

    def sum_mod(a, m):
        return (sum(a) % m + m) % m

    def solve_subarray(a, low, high):
        if low == high:
            return 0 if a[low] % 2 == 0 else 1
        mid = (low + high) // 2
        left = solve_subarray(a, low, mid)
        right = solve_subarray(a, mid + 1, high)
        if sum_mod(accumulate(a[mid:high + 1]), 2) == 0:
            return min(left, right)
        else:
            return 1 + min(left + right - (high - mid), left + solve_subarray(a, low, mid))

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        print(solve_subarray(a, 0, n - 1))

