import heapq

def solve(n, strengths):
    max_heaps = [[] for _ in range(n)]
    min_heaps = [[] for _ in range(n)]

    for i, strength in enumerate(strengths):
        heapq.heappush(max_heaps[i], -strength)
        heapq.heappush(min_heaps[i], strength)

        for j in range(i):
            if max_heaps[j] and max_heaps[j][0] > min_heaps[i][0]:
                heapq.heappushpop(max_heaps[i], -min_heaps[j][0])
            if min_heaps[j] and min_heaps[j][0] < max_heaps[i][0]:
                heapq.heappushpop(min_heaps[i], -max_heaps[j][0])

    result = [0] * n
    for i in range(n):
        result[i] = max_heaps[i][0] - strengths[i]

    return result

