from math import ceil

def solve(b, s, n, used, permutation):
    if s == 0:
        permutation.sort()
        return True

    if not s or n == 0:
        return False

    if used[b[n - 1]]:
        return False

    used[b[n - 1]] = True
    if solve(b, s - b[n - 1], n - 1, used, permutation):
        permutation.append(b[n - 1])
        return True

    used[b[n - 1]] = False
    for i in range(b[n - 1] + 1, -1, -ceil(b[n - 1] / n) * n):
        if i + b[n - 1] <= s and not used[i]:
            used[i] = True
            if solve(b, s - (i + b[n - 1]), n, used, permutation):
                permutation.append(i)
                permutation.append(b[n - 1])
                return True
            used[i] = False
    return False

