import functools

def abs_diff(arr):
    n = len(arr)
    dp = [[0] * 200005 for _ in range(n)]

    @functools.lru_cache(None)
    def dfs(i, s):
        if i == n:
            return abs(s)
        res = dp[i][s]
        if res != 0:
            return res
        for j in range(i, n):
            dp[i][s + arr[j]] = dfs(j + 1, s + arr[j])
            dp[i][s - arr[j]] = max(dp[i][s - arr[j]], dfs(j + 1, s - arr[j]))
        return res = max(dp[i][s + arr[i]], dp[i][s - arr[i]])

    return dfs(0, 0)

