@functools.lru_cache(maxsize=None)
def dp(i, s1, s2):
    if i == 0:
        return abs(s1) - abs(s2)

    res = float('-inf')
    for j in range(i):
        dp_val = dp(i - j - 1, s1 + a[j], s2)
        res = max(res, dp_val)

    return res

