from typing import List, Dict

@functools.lru_cache(maxsize=None)
def dfs(index: int, group: int, current_sum: int, a: List[int], memo: Dict[str, int]):
    key = f"{index}_{group}_{current_sum}"
    if index == len(a):
        if group == 1:
            return abs(current_sum)
        else:
            return -1 * abs(current_sum)

    if key in memo:
        return memo[key]

    max_diff = -1 * abs(current_sum)
    for i in range(index, len(a)):
        max_diff = max(max_diff, dfs(i + 1, 1 ^ group, current_sum + a[i], a, memo) - dfs(i + 1, group, current_sum, a, memo))

    memo[key] = max_diff
    return max_diff

def solve(a: List[int]):
    return dfs(0, 1, 0, a, {})

