        if size == 1:
            return a[i] == 1
        for j in range(i+1, min(i+k, len(a))):
            if a[j] == 1:
                a[i:j] = [1] * (j - i)
                if solve(a, k):
                    return True
                a[i:j] = a[i:]
            if j + k - 1 < len(a) and dfs(j, k):
                return True
        return False

    for i in range(len(a)):
        if dfs(i, min(k, len(a) - i + 1)):
            return True
    return False

