def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))

        # Initialize UF data structure
        parent = list(range(n))
        rank = [0] * n
        size = [1] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px = find(x)
            py = find(y)
            if px == py:
                return
            if rank[px] < rank[py]:
                parent[px] = py
                size[py] += size[px]
            else:
                parent[py] = px
                size[px] += size[py]

        # Initialize DFS data structure
        dfs_visited = [False] * n
        dfs_index = defaultdict(list)
        for i in range(n):
            for j in range(i + 1, n):
                if (i % k == j % k):
                    dfs_index[(find(i), find(j))].append((i, j))

        # Perform DFS to find the maximum score
        max_score = 0
        def dfs(x, y, cur_score, cur_size):
            nonlocal max_score
            dfs_visited[x] = dfs_visited[y] = True
            cur_score += a[x] + a[y]
            cur_size += 2
            for i, j in dfs_index[(find(x), find(y))]:
                if not dfs_visited[i] and not dfs_visited[j]:
                    dfs(i, j, cur_score, cur_size)
                    max_score = max(max_score, cur_score * cur_size // k)
            dfs_visited[x] = dfs_visited[y] = False

        for i in range(n):
            if not dfs_visited[i]:
                dfs(i, i, a[i], 1)

        print(max_score)

