import sys

def dijkstra(n, k, a):
    dist = [float('inf')] * n
    dist[0] = 0
    pq = [(0, 0)]

    while pq:
        d, i = heapq.heappop(pq)

        if i >= n:
            continue

        for j in range(i, min(i + k, n)):
            dist[j] = min(dist[j], d + a[i])

        for j in range(i + k, n, k):
            heapq.heappush(pq, (dist[i] + a[j], j))

    return max(dist)

