def build_segment_tree(arr, n):
    size = 4 * n
    tree = [0] * size
    for i in range(n):
        tree[i + n] = arr[i]
    for i in range(n - 1, 0, -1):
        tree[i] = max(tree[2 * i], tree[2 * i + 1])
    return tree

def update(tree, n, pos, val, idx):
    pos += n
    tree[idx] = val
    while idx > 1:
        idx //= 2
        tree[idx] = max(tree[2 * idx], tree[2 * idx + 1])

def query(tree, n, l, r, q, idx, val):
    if r < l:
        return 0
    if l <= q <= r:
        return tree[idx]
    m = (l + r) // 2
    return max(query(tree, n, l, m, q, 2 * idx, val), query(tree, n, m + 1, r, q, 2 * idx + 1, val))

