def extended_gcd(a, b):
    if a == 0:
        return (0, 1, 0, 0) if b == 0 else (b, 0, 1, 0)
    g, y, x, z = extended_gcd(b % a, a)
    return (a, z - (b // a) * z, x - (b // a) * y, y)

