def solve(n):
    permutations = list(itertools.permutations(list(range(1, n + 1))))
    for i in range(len(permutations) - 1, -1, -1):
        if sum(permutations[i]) > sum(permutations[i - 1]):
            break
        if sum(permutations[i]) == sum(permutations[i - 1]):
            if permutations[i - 1][-1] < permutations[i][-1]:
                permutations.pop(i)
