        if x < q[i]:
            x += q[i]
        else:
            x = 0

    if x < q[0]:
        x += q[0]
    else:
        x = 0
        q.append(q.popleft())

    if x == solve(n - 1, q, 0):
        print(*q)
        return x
    else:
        x += 1

