def solve(N, M):
    # Initialize a list of zeros with N elements
    grid = [0] * (M * N)

    # Fill the grid with numbers
    for i in range(1, M + 1):
        grid[i - 1] = i
    for i in range(M + 1, M * 2 + 1):
        grid[i - 1] = i
    for i in range(M * 2 + 1, M * 3 + 1):
        grid[i - 1] = i
    for i in range(M * 3 + 1, M * 4 + 1):
        grid[i - 1] = i
    # Continue this pattern until the last row

    # Calculate the number of tight dominoes using bitwise operations
    dominoes = 0
    for i in range(1, len(grid) - 1):
        if grid[i] and grid[i + 1] and grid[i] + 1 == grid[i + 1]:
            dominoes |= (1 << (grid[i] - 1))
    return sum(set(dominoes))

