    if not is_valid(x, y, n, m):
        return False

    if player == 1 and board[x][y]:
        board[x][y] = False
        for dx, dy in [(2, 0), (0, 2)]:
            if dfs(x + dx, y + dy, n, m, 2, board):
                return True
        board[x][y] = True

    elif player == 2 and not board[x][y]:
        board[x][y] = True
        for dx, dy in [(2, 0), (0, 2)]:
            if dfs(x + dx, y + dy, n, m, 1, board):
                return True
        board[x][y] = False

