def solve():
    n = int(input())
    if n == 1:
        print(1)
        print(1)
        return

    perms = list(itertools.permutations(range(1, n + 1)))
    chains = []
    for perm in perms:
        fixedness = sum(i == j for i, j in zip(perm, range(1, n + 1)))
