            chains.append((perm, fixedness))
            continue
        for prev_perm, prev_fixedness in chains:
            if prev_fixedness + 1 == fixedness:
                chains.append((perm, fixedness))
                break

    max_chain_len = max(len(chain) for chain, _ in chains)
