def bfs(grid, start, end, portals, power):
    queue = [(0, start, [start])]
    visited = set([start])
    while queue:
        energy, current, path = heapq.heappop(queue)
        if current == end:
            return energy
        for neighbor in [(current[0] - 1, current[1]), (current[0] + 1, current[1]), (current[0], current[1] - 1), (current[0], current[1] + 1)]:
            if 0 <= neighbor[0] < len(grid) and 0 <= neighbor[1] < len(grid[0]) and (not neighbor in visited or neighbor in portals):
                visited.add(neighbor)
                heapq.heappush(queue, (energy + power if neighbor in portals else energy + 1, neighbor, path + [neighbor]))
    return -1

