def dijkstra(n, edges):
    dist = [float('inf')] * n
    dist[0] = 0
    q = [(0, 0)]

    while q:
        d, u = heapq.heappop(q)
        if dist[u] < d:
            continue
        for v, w in edges[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                heapq.heappush(q, (dist[v], v))

    return dist

