def mobius(n):
    mu = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i, n + 1, i):
            mu[j] -= 1
        mu[i] += sum(mu[k] for k in range(i, n + 1, i))
    return mu

def solve(n):
    mu = mobius(n)
    weights = [0] * (n + 1)
    for i in range(1, n + 1):
        weights[i] = sum(mu[j] for j in range(1, n + 1) if i % j == 0)
    weights = list(reversed(sorted(weights)))
    permutation = [0] * n
    for i in range(n - 1, -1, -1):
        permutation[weights[i]] = i + 1
    return permutation

