import sys

def factor_count(n):
    count = [0] * (n + 1)
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count[i] += 1
            if i != n // i:
                count[n // i] += 1
    return count

def solve(n):
    dp = [[0] * n for _ in range(n + 1)]
    divisor_count = factor_count(n)

    for i in range(1, n + 1):
        for d in range(1, i + 1):
            if i % d == 0:
                dp[i][i] = divisor_count[d]
                if i > d:
                    dp[i][d] += dp[i - d][d]

    min_weight = float('inf')
    min_perm = [0] * n
    for i in range(1, n + 1):
        weight = sum(dp[n][i])
        if weight < min_weight:
            min_weight = weight
            min_perm = list(reversed([i] + list(range(1, i))))

    return min_perm

