from collections import deque

def solve(a, b):
    if len(a) != len(b):
        return False

    stack = deque(a)
    dp = [0] * (len(a) + 1)
    dp[-1] = 1 if a[-1] == b[-1] else 0

    for i in range(len(a) - 1, -1, -1):
        if stack[0] == '0':
            if stack[1] == '1':
                stack.popleft()
                stack.popleft()
                dp[i] = dp[i + 1]
            else:
                dp[i] = dp[i + 1]
        elif stack[0] == '1':
            if stack[1] == '0':
                stack.popleft()
                stack.popleft()
                dp[i] = dp[i + 1] | 1 << (len(a) - i)
            else:
                dp[i] = dp[i + 1] | (dp[i + 1] >> (len(a) - i))

    return dp[0] == (1 << len(a)) - 1

