import itertools

def solve(a, b):
    if len(a) != len(b):
        return False

    def operation1(seq):
        for i in range(1, len(seq)):
            if seq[i] > seq[i - 1]:
                seq[i - 1], seq[i] = seq[i], seq[i - 1]
                return seq
        return seq

    def operation2(seq):
        for i in range(1, len(seq)):
            if seq[i] < seq[i - 1]:
                seq[i - 1], seq[i] = seq[i], seq[i - 1]
                return seq
        return seq

    a_ops = [operation1(a), operation2(a)]
    b_ops = [operation1(b), operation2(b)]

    for a_op, b_op in zip(a_ops, b_ops):
        if a_op != b_op:
            return False

    return all(a_op == b_op for a_op, b_op in zip(a_ops, b_ops))

