import re

def solve(a, b, n):
    def dfs(i, sequence):
        if i == n:
            return sequence
        moves = re.findall(r'[UD]{' + str(b[i]) + '}', b[i-1])
        for move in moves:
            new_sequence = sequence[:i] + [int(sequence[i-1] + move)]
            dfs(i+1, new_sequence)

    dfs(1, [0]*n)
    result = []
    for i in range(n):
        result[i] = str(a[i] + solve(a, b, n)[n-1] - solve(a, b, n)[i]) % 10
    return result

