import itertools

def solve(s):
    n = len(s)
    dp = [0] * (1 << n)
    dp[0] = 1

    def dfs(mask, index):
        if index == n:
            return dp[mask]
        for i in range(index, n):
            if (mask >> i) & 1 == 0 and (mask >> (i - 1)) & 1 == 1:
                dp[mask | (1 << i)] += dp[mask]
                dfs(mask | (1 << i), i + 1)
        return dp[mask]

    for i in range(1, (1 << n)):
        dfs(i, 0)

    return sum(dp) - dp[0]

from functools import lru_cache

def solve(s):
    n = len(s)
    @lru_cache(None)
    def dp(i):
        if i == 0:
            return 0
        return dp(i - 1) + (1 if s[i - 1] != 'A' or dp(i - 2) < dp(i - 3) else 0)

    return dp(n - 1) + dp(n - 2) if n > 1 else 1

