import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def extended_euclidean_algorithm(a, b):
    if a == 0:
        return (0, 1, b)
    else:
        g, y, x = extended_euclidean_algorithm(b % a, a)
        return (g, x - (b // a) * x, y)

def solve(n):
    d = math.gcd(n, n - 1)
    if d > 1:
        d = n // d
        g, x, y = extended_euclidean_algorithm(d, n - 1)
        if g > 1:
            d = g

    permutation = list(itertools.permutations(range(1, n + 1)))
    max_cost = 0
    best_permutation = None
    for p in permutation:
        cost = sum(1 for i in range(len(p) - 1) if p[i] * d == p[i + 1])
        if cost > max_cost:
            max_cost = cost
            best_permutation = list(p)

    print(d)
    print(*best_permutation)

