import sys

def solve(n, d, perm, cost, max_cost):
    if len(perm) == n:
        if cost > max_cost:
            max_cost = cost
        return

    for i in range(len(perm), n):
        if perm[i] % d == perm[-1] % d:
            continue
        perm_copy = perm[:]
        perm_copy.append(i + 1)
        perm_cost = cost
        for j in range(len(perm), i, -1):
            if perm_copy[j] % d == perm_copy[j - 1] % d:
                perm_cost += 1
        solve(n, d, perm_copy, perm_cost, max_cost)

