def solve(n, m, memo={}):
    if (n, m) in memo:
        return memo[(n, m)]
    if n == 1 and m == 1:
        memo[(n, m)] = 0
        return 0
    if n == 1 or m == 1:
        memo[(n, m)] = float('inf')
        return float('inf')

    memo[(n, m)] = min(solve(n, m - 1) + n, solve(n - 1, m) + m)

    for i in range(1, min(n, m) + 1):
        if (n - i, m) in memo:
            memo[(n, m)] = min(memo[(n, m)], solve(n - i, m) + i)
        if (n, m - i) in memo:
            memo[(n, m)] = min(memo[(n, m)], solve(n, m - i) + i)

    return memo[(n, m)]

