from the starting cell (1, 1). We will use a 2D array `dp` to store the minimum cost to reach each cell.

Here is the Python code:

```python
import sys
from functools import lru_cache

def solve():
    n, m = map(int, input().strip().split())
    a = [[(i - 1) * m + j for j in range(1, m + 1)] for i in range(1, n + 1)]
    dp = [[0] * m for _ in range(n)]

    @lru_cache((n, m))
    def dfs(i, j):
        if i == n and j == m:
            return 0
        if dp[i][j] != 0:
            return dp[i][j]
        cost = float('inf')
        if i + 1 <= n:
            cost = min(cost, a[i][j] + dfs(i + 1, j))
        if j + 1 <= m:
            cost = min(cost, a[i][j] + dfs(i, j + 1))
        dp[i][j] = cost
        return cost

    print(dfs(1, 1))
